import unittest


class StyleCheck(unittest.TestCase):
    def test_no_tabs(self):
        with open("calc.py") as f:
            self.assertNotIn("\t", f.read())

    def test_line_length(self):
        with open("calc.py") as f:
            self.assertTrue(all(len(line) < 20 for line in f))
